def lex_largest_string(word: str, numFriends: int) -> str:
    # With one friend the only split is the whole word
    if numFriends == 1:
        return word

    n = len(word)
    max_len = n - numFriends + 1  # longest possible split part

    # Best part starting at each index is the longest valid one (truncated at the end)
    return max(word[i:i + max_len] for i in range(n))
